function rng(seed) { let s = seed >>> 0; return () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const hashStr = s => { let h = 2166136261; for (const ch of s) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return h >>> 0; };
const HOUSES = [];
for (const v of VILLAGES) {
  const [cx, cy] = ll2m(v.la, v.lo), R = rng(hashStr(v.n));
  const segs = [];
  for (const rd of ROADS) for (let i = 0; i < rd.pts.length - 1; i++) {
    const [ax, ay] = rd.pts[i], [bx, by] = rd.pts[i + 1];
    for (let t = 0; t <= 1; t += 0.05) { const px = ax + (bx - ax) * t, py = ay + (by - ay) * t; if (Math.hypot(px - cx, py - cy) < v.r) { segs.push([ax, ay, bx, by]); break; } }
  }
  v.cx = cx; v.cy = cy; v.houses = [];
  for (let k = 0; k < v.k; k++) {
    let x, y, rot;
    if (segs.length && R() < 0.8) {
      const s = segs[(R() * segs.length) | 0]; let tries = 0;
      do { const t = R(); x = s[0] + (s[2] - s[0]) * t; y = s[1] + (s[3] - s[1]) * t; tries++; } while (Math.hypot(x - cx, y - cy) > v.r && tries < 12);
      const ang = Math.atan2(s[3] - s[1], s[2] - s[0]), side = R() < 0.5 ? -1 : 1, off = 16 + R() * 18;
      x += -Math.sin(ang) * off * side; y += Math.cos(ang) * off * side; rot = ang * 180 / Math.PI;
    } else { const a = R() * Math.PI * 2, d = Math.sqrt(R()) * v.r * 0.8; x = cx + Math.cos(a) * d; y = cy + Math.sin(a) * d; rot = R() * 90; }
    const hse = { x, y, w: 10 + R() * 12, h: 7 + R() * 6, rot };
    v.houses.push(hse); HOUSES.push(hse);
  }
}


